import { useLocalSearchParams } from 'expo-router';
import { StyleSheet, View } from 'react-native';
import { Screen, Text } from '@/components/ui';
import { privacyPolicy, termsOfService } from '@/generated/legal';
import { spacing } from '@/theme/tokens';

/**
 * In-app privacy policy / terms. Text comes from legal/*.md (generated by
 * `npm run brand:sync`). The same text is published on the website for the stores.
 */
export default function LegalScreen() {
  const { doc } = useLocalSearchParams<{ doc: 'privacy' | 'terms' }>();
  const md = doc === 'terms' ? termsOfService : privacyPolicy;
  return (
    <Screen>
      <View style={styles.wrap}>
        {md.split('\n').map((line, i) => {
          if (!line.trim()) return null;
          if (line.startsWith('# ')) return <Text key={i} variant="title">{line.slice(2)}</Text>;
          if (line.startsWith('## ')) return <Text key={i} variant="heading" style={styles.h2}>{line.slice(3)}</Text>;
          const text = line.replace(/\*\*(.+?)\*\*/g, '$1').replace(/^_(.+)_$/, '$1');
          if (line.startsWith('- ')) return <Text key={i} tone="muted">• {text.slice(2)}</Text>;
          return <Text key={i} tone={line.startsWith('_') ? 'faint' : 'muted'} variant={line.startsWith('_') ? 'small' : 'body'}>{text}</Text>;
        })}
      </View>
    </Screen>
  );
}

const styles = StyleSheet.create({ wrap: { gap: spacing.sm }, h2: { marginTop: spacing.md } });
